import {
  castSpell,
  chooseCountTargets,
  queueWardTriggers,
  queueBecomesTargetedTriggers,
  consumePlayFromZonePermission,
} from '../casting/cast';
export { queueWardTriggers, queueBecomesTargetedTriggers } from '../casting/cast';
import { activationManaSources, activationSacrificeReservation } from '../mana/activation';

/**
 * Applying a chosen priority action: playing a land, casting a spell (with auto-payment),
 * moving the companion to hand. The option was generated by `computePriorityOptions`, so
 * legality holds; payment plans are recomputed here and must succeed.
 */

import type { ObjectId } from '@mtg/shared';
import {
  abilityForModes,
  abilityModeLabel,
  abilityModeSelections,
  abilityModeTargetSlots,
  slotIsActive,
} from './ability-modes';

import { evaluateCondition } from '../cards/condition';
import type { AbilityCost } from '../cards/definition';
import type { DecisionOutcome, GameGen } from '../decisions';
import { payAbilityCosts, payManaCost } from '../effects/resolve';
import { computeCharacteristics } from '../effects/continuous';

import { emit, debug } from '../log/log';

import { emptyCost, subtractGeneric, totalPips, withX } from '../mana/cost';
import {
  discardCard,
  makePermanent,
  moveObject,
  queueActivationTriggers,
  queuePlayerTriggersForEvent,
} from '../state/objects';
import {
  activatingAbilitiesBlockedFor,
  colorsOf,
  gatherRuleStatics,
  getDefByOracleId,
  abilityOfPermanent,
  targetingFromDefinition,
} from '../state/queries';
import type {
  EngineCardObject,
  EnginePermanent,
  EnginePlayerState,
  EngineStackObject,
  GameContext,
} from '../state/types';
import type { PriorityActionPayload } from './legal';
import {
  activationCostReductionFor,
  computeTargetOptions,
  handActivationCost,
  manaPortionOf,
  graveyardActivationCost,
  turnFaceUpCosts,
} from './legal';
import { breakYieldsForStop } from '../turn/stops';

/** Run an activation's cost payment, returning the life paid as part of it (Verrak). */
function* withLifePaidTally<T>(ctx: GameContext, pay: GameGen<T>): GameGen<[T, number]> {
  const tally = { amount: 0 };
  ctx.costLifePaid = tally;
  try {
    const result = yield* pay;
    return [result, tally.amount];
  } finally {
    delete ctx.costLifePaid;
  }
}

/**
 * Pay a whole activation cost. A source that is itself tapped as a cost must be excluded from
 * the mana plan, so those non-mana costs are paid first. Sacrifice-another costs are different:
 * the player may use the permanent for mana before sacrificing it, and the sacrifice choice is
 * interactive. Paying mana first keeps a legal action from becoming unpayable when the player
 * chooses a mana-producing artifact as the sacrifice.
 */
function* payActivationCosts(
  ctx: GameContext,
  player: EnginePlayerState,
  perm: EnginePermanent,
  costs: readonly AbilityCost[],
  announcedX = 0,
): GameGen<{ stationPower?: number }> {
  const mana = manaPortionOf(costs);
  const paysManaBeforeSacrifice = costs.some((cost) => cost.kind === 'sacrificeOther');
  const payMana = function* (): GameGen<void> {
    if (totalPips(mana) > 0) {
      // The purpose must match the one `computePriorityOptions` used to decide affordability, or
      // restricted mana that made the ability appear payable would not be spendable here.
      const spendsSource = costs.some(
        (cost) => cost.kind === 'tap' || cost.kind === 'sacrificeSelf' || cost.kind === 'exileSelf',
      );
      // Mana is paid before the ability's own sacrifice, so keep what that sacrifice needs away
      // from mana abilities that sacrifice (Illuminor Szeras), as legality priced it.
      const reserved = paysManaBeforeSacrifice
        ? activationSacrificeReservation(ctx, player, perm, costs, mana, announcedX)
        : null;
      yield* payManaCost(
        ctx,
        player,
        mana,
        { kind: 'activateAbility', sourceOracleId: perm.oracleId },
        spendsSource ? [perm.cardId] : [],
        reserved ?? new Set(),
      );
    }
  };
  if (paysManaBeforeSacrifice) yield* payMana();
  const paymentScope = yield* payAbilityCosts(
    ctx,
    player,
    perm,
    costs,
    'tap',
    announcedX,
    (candidate, remaining) =>
      activationManaSources(
        ctx,
        player,
        perm,
        remaining,
        paysManaBeforeSacrifice ? emptyCost() : mana,
        announcedX,
        [perm.cardId, candidate.cardId],
      ) !== null,
  );
  if (!paysManaBeforeSacrifice) {
    yield* payMana();
  }
  return paymentScope;
}

/**
 * Ward (CR 702.21b): "whenever this becomes the target of a spell or ability an opponent
 * controls, counter it unless that player pays `<cost>`".
 *
 * Modeled as a *triggered ability*, not as a targeting restriction, and that is the load-bearing
 * decision. "Unless the controller pays" is a decision, and `isTargetStillLegal` — the function
 * a legality filter would have to live in — is a pure predicate that cannot ask a player
 * anything. As a trigger it also behaves correctly: it goes on the stack above the spell, so
 * the spell is still countered if ward resolves, and other responses can happen in between.
 */
export function* applyPriorityAction(
  ctx: GameContext,
  player: EnginePlayerState,
  payload: PriorityActionPayload,
  outcome: DecisionOutcome,
): GameGen<void> {
  const s = ctx.state;
  switch (payload.kind) {
    case 'pass':
      throw new Error('engine bug: pass is not applied via applyPriorityAction');

    case 'playLand': {
      const temporaryExileCard = ctx.state.exile.find((card) => card.id === payload.objectId);
      if (payload.fromExile === true && temporaryExileCard?.castOnlyUntilEot === true) {
        throw new Error('a cast-only permission does not allow playing a land');
      }
      const sourceZone =
        payload.fromLibraryTop === true
          ? player.library
          : payload.fromGraveyard === true
            ? player.graveyard
            : payload.fromExile === true
              ? ctx.state.exile
              : player.hand;
      const obj = sourceZone.find((o) => o.id === payload.objectId);
      if (obj === undefined) throw new Error('engine bug: land to play not in its source zone');
      if (payload.fromLibraryTop === true) {
        consumePlayFromZonePermission(ctx, player, obj, 'libraryTop', payload.zoneBudgetType);
      }
      if (payload.fromGraveyard === true) {
        consumePlayFromZonePermission(ctx, player, obj, 'graveyard', payload.zoneBudgetType);
      }
      const def = getDefByOracleId(ctx, obj.oracleId, obj.name);
      const mdfc =
        payload.alternativeCast === 'mdfc'
          ? (def.alternativeCasts?.[payload.altIndex ?? 0] ??
            def.alternativeCasts?.find((alt) => alt.kind === 'mdfc'))
          : undefined;
      if (
        payload.alternativeCast === 'mdfc' &&
        (mdfc?.kind !== 'mdfc' || mdfc.landFace === undefined)
      ) {
        throw new Error('missing MDFC land face');
      }
      player.landsPlayedThisTurn += 1;
      emit(
        ctx,
        'playLand',
        { player: player.id, name: mdfc?.landFace?.name ?? obj.name, cardId: obj.cardId },
        player.id,
      );
      debug(ctx, 'legalActions', `${player.id} plays ${mdfc?.landFace?.name ?? obj.name}`);
      yield* moveObject(ctx, obj, {
        zone: 'battlefield',
        controllerId: player.id,
        ...(mdfc?.kind === 'mdfc' ? { face: 'back' as const } : {}),
      });
      return;
    }

    case 'castSpell':
      yield* castSpell(ctx, player, payload, outcome);
      return;

    case 'activateAbility': {
      // Hand-zone activation (CR 112.6a) — cycling and its typed variants. Same short path as
      // the graveyard branch below and for the same reason: the source is a card in a hidden
      // zone with no `EnginePermanent` behind it.
      //
      // `discardSelf` is paid BEFORE the mana, which is what makes cycling behave correctly:
      // the card is in the graveyard while the ability is on the stack (CR 702.29a), so a
      // "whenever you cycle a card" or madness-style observer sees it there, and the card can
      // never be spent twice. `computePriorityOptions` refuses to offer a hand ability with any
      // other non-mana cost, so there is nothing else to pay here.
      if (payload.fromHand === true) {
        const card = player.hand.find((c) => c.id === payload.objectId);
        if (card === undefined) throw new Error('engine bug: hand ability source not in hand');
        const def = getDefByOracleId(ctx, card.oracleId, card.name);
        const activated = def.activatedAbilities[payload.index];
        if (activated === undefined) throw new Error('engine bug: activated ability index invalid');

        // CR 601.2c — targets first, then costs. Same validation as the battlefield path below.
        const targets: ObjectId[] = [];
        for (const [slot, spec] of activated.ability.targets.entries()) {
          if (spec.count !== undefined) continue;
          const choice = outcome.targets.get(slot);
          if (choice === undefined)
            throw new Error(`missing target for slot ${slot} of ${card.name}`);
          if (
            !computeTargetOptions(
              ctx,
              spec,
              player.id,
              targetingFromDefinition(def, 'ability'),
            ).includes(choice)
          ) {
            throw new Error(`illegal target ${choice} for slot ${slot} of ${card.name}`);
          }
          targets.push(choice);
        }

        const counted = yield* chooseCountTargets(
          ctx,
          activated.ability,
          player.id,
          card.cardId,
          targets,
          undefined,
          targetingFromDefinition(def, 'ability'),
        );
        const allTargets = [...targets, ...Object.values(counted.countTargets).flat()];

        // The reduced cost, computed exactly as `computePriorityOptions` computed it when it
        // decided this action was affordable — a channel land's own "costs {1} less to activate
        // for each legendary creature you control" is on a card in HAND, which
        // `activationCostReductionFor` cannot see. Read BEFORE the discard, because the card
        // leaving hand must not change what it costs.
        const manaCost = handActivationCost(ctx, def, activated.costs, player.id, card.cardId);

        const [, lifePaid] = yield* withLifePaidTally(
          ctx,
          (function* (): GameGen<void> {
            if (activated.costs.some((c) => c.kind === 'discardSelf')) {
              yield* discardCard(ctx, card, player.id, 'cost');
            }
            if (totalPips(manaCost) > 0) {
              yield* payManaCost(ctx, player, manaCost, {
                kind: 'activateAbility',
                sourceOracleId: card.oracleId,
              });
            }
          })(),
        );

        const description = activated.ability.description ?? 'activated ability';
        const id = `o-${s.nextObjectNum++}` as ObjectId;
        const stackEntry: EngineStackObject = {
          id,
          sourceId: id,
          controllerId: player.id,
          kind: 'activatedAbility' as const,
          description: `${card.name} — ${description}`,
          targets,
          ...(Object.keys(counted.countTargets).length > 0
            ? { countTargets: counted.countTargets }
            : {}),
          ...(Object.keys(counted.divisionAmounts).length > 0
            ? { divisionAmounts: counted.divisionAmounts }
            : {}),
          card: null,
          ability: activated.ability,
          sourceOracleId: card.oracleId,
          sourceCardId: card.cardId,
          isCommanderCast: false,
        };
        s.stack.push(stackEntry);
        breakYieldsForStop(ctx, stackEntry);
        emit(
          ctx,
          'activateAbility',
          {
            player: player.id,
            source: card.name,
            cardId: card.cardId,
            description,
            targets: allTargets,
          },
          player.id,
        );
        queueWardTriggers(ctx, player.id, id, allTargets);
        queueBecomesTargetedTriggers(ctx, player.id, allTargets);
        queueActivationTriggers(ctx, stackEntry, lifePaid);
        debug(ctx, 'stack', `${player.id} activates ${card.name} (hand) — ${description}`);
        return;
      }

      // Graveyard-zone activation (CR 112.6a/602.5c, Runehorn Hellkite) — the source has no
      // `EnginePermanent` (tap/sacrifice/etc. machinery), so it takes its own short path: pay
      // mana directly, pay `exileSelfFromGraveyard` by moving the card, and push a stack entry
      // built from the card's own fields the same way `resolveTopOfStack` builds `source` for
      // any activated ability — it never dereferences a battlefield permanent.
      if (payload.fromGraveyard === true) {
        const card = player.graveyard.find((c) => c.id === payload.objectId);
        if (card === undefined)
          throw new Error('engine bug: graveyard ability source not in graveyard');
        const def = getDefByOracleId(ctx, card.oracleId, card.name);
        const activated = [
          ...def.activatedAbilities,
          ...(ctx.state.temporaryGraveyardAbilities[card.cardId] ?? []),
        ][payload.index];
        if (activated === undefined) throw new Error('engine bug: activated ability index invalid');

        // Every mana component, for the same purpose `computePriorityOptions` priced it with —
        // otherwise mana that may only pay for activations would make an offered action unpayable.
        const manaCost = graveyardActivationCost(ctx, player.id, manaPortionOf(activated.costs));
        const [, lifePaid] = yield* withLifePaidTally(
          ctx,
          (function* (): GameGen<void> {
            if (totalPips(manaCost) > 0) {
              yield* payManaCost(ctx, player, manaCost, {
                kind: 'activateAbility',
                sourceOracleId: card.oracleId,
              });
            }
            if (activated.costs.some((c) => c.kind === 'exileSelfFromGraveyard')) {
              yield* moveObject(ctx, card, { zone: 'exile' });
            }
          })(),
        );

        const description = activated.ability.description ?? 'activated ability';
        const id = `o-${s.nextObjectNum++}` as ObjectId;
        const stackEntry: EngineStackObject = {
          id,
          sourceId: id,
          controllerId: player.id,
          kind: 'activatedAbility' as const,
          description: `${card.name} — ${description}`,
          targets: [],
          card: null,
          ability: activated.ability,
          sourceOracleId: card.oracleId,
          sourceCardId: card.cardId,
          isCommanderCast: false,
        };
        s.stack.push(stackEntry);
        breakYieldsForStop(ctx, stackEntry);
        emit(
          ctx,
          'activateAbility',
          { player: player.id, source: card.name, cardId: card.cardId, description, targets: [] },
          player.id,
        );
        queueActivationTriggers(ctx, stackEntry, lifePaid);
        debug(ctx, 'stack', `${player.id} activates ${card.name} (graveyard) — ${description}`);
        return;
      }

      const perm = ctx.state.battlefield.find((p) => p.id === payload.objectId);
      if (perm === undefined) throw new Error('engine bug: ability source not on the battlefield');
      if (activatingAbilitiesBlockedFor(ctx, player.id, perm)) {
        throw new Error('activated abilities of this permanent are currently forbidden');
      }
      const def = getDefByOracleId(ctx, perm.oracleId, perm.name);
      const activated = (computeCharacteristics(ctx, perm).activatedAbilities ??
        def.activatedAbilities)[payload.index];
      if (activated === undefined) throw new Error('engine bug: activated ability index invalid');
      if (
        activated.condition !== undefined &&
        !evaluateCondition(ctx, activated.condition, {
          cardId: perm.cardId,
          controllerId: player.id,
        })
      ) {
        throw new Error('activated ability condition is not met');
      }
      if (activated.exhaust === true && perm.exhaustedAbilities?.includes(payload.index) === true) {
        throw new Error('this exhaust ability has already been activated');
      }

      // CR 601.2b/602.2b: a modal ability's mode was announced by the option itself, before
      // targets. Fold it in now so the stack entry, fizzle check and executor see only the
      // chosen modes' effects, and only those modes' target slots are announced.
      const modes = activated.ability.modes;
      if ((modes === undefined) !== (payload.modes === undefined)) {
        throw new Error(`engine bug: mode announcement mismatch for ${perm.name}`);
      }
      const selectedModes = payload.modes;
      if (
        modes !== undefined &&
        selectedModes !== undefined &&
        !abilityModeSelections(modes).some(
          (candidate) =>
            candidate.length === selectedModes.length &&
            candidate.every((mode, i) => mode === selectedModes[i]),
        )
      ) {
        throw new Error(`engine bug: invalid modes ${selectedModes.join(',')} for ${perm.name}`);
      }
      const announced =
        selectedModes === undefined
          ? activated.ability
          : abilityForModes(activated.ability, selectedModes);
      const activeSlots =
        modes === undefined || selectedModes === undefined
          ? undefined
          : abilityModeTargetSlots(modes, selectedModes);
      const modeLabel =
        modes === undefined || selectedModes === undefined
          ? undefined
          : abilityModeLabel(modes, selectedModes);

      // CR 601.2c/601.2h: targets are chosen, then costs are paid, then the ability is on the
      // stack. Paying is one indivisible act and happens even if the ability never resolves —
      // which is why sacrificing the source does not remove the ability from the stack.
      // Indexed by slot, so an unchosen mode's slot stays empty (as a modal spell's does).
      const targets: ObjectId[] = [];
      for (const [slot, spec] of activated.ability.targets.entries()) {
        if (spec.count !== undefined || !slotIsActive(activeSlots, slot)) continue;
        const choice = outcome.targets.get(slot);
        if (choice === undefined)
          throw new Error(`missing target for slot ${slot} of ${perm.name}`);
        const legal = computeTargetOptions(
          ctx,
          spec,
          player.id,
          abilityOfPermanent(ctx, perm),
          undefined,
          targets,
          perm.cardId,
        );
        if (!legal.includes(choice)) {
          throw new Error(`illegal target ${choice} for slot ${slot} of ${perm.name}`);
        }
        targets[slot] = choice;
      }

      const counted = yield* chooseCountTargets(
        ctx,
        announced,
        player.id,
        perm.cardId,
        targets,
        activeSlots,
        abilityOfPermanent(ctx, perm),
      );
      const allTargets = [
        ...targets.filter((id): id is ObjectId => id !== undefined),
        ...Object.values(counted.countTargets).flat(),
      ];
      const description =
        (activated.ability.description ?? 'activated ability') +
        (modeLabel === undefined ? '' : ` [mode: ${modeLabel}]`);
      const id = `o-${s.nextObjectNum++}` as ObjectId;
      // Snapshot before paying: a sacrifice cost removes the permanent, and the stack entry
      // must still name its source (CR 608.2f — the ability resolves regardless).
      const stackEntry: EngineStackObject = {
        id,
        sourceId: perm.id,
        sourceTransformations: perm.transformations ?? 0,
        controllerId: player.id,
        kind: 'activatedAbility' as const,
        description: `${perm.name} — ${description}`,
        targets,
        ...(Object.keys(counted.countTargets).length > 0
          ? { countTargets: counted.countTargets }
          : {}),
        ...(Object.keys(counted.divisionAmounts).length > 0
          ? { divisionAmounts: counted.divisionAmounts }
          : {}),
        card: null,
        ability: announced,
        sourceColors: colorsOf(ctx, perm),
        sourceOracleId: perm.oracleId,
        sourceCardId: perm.cardId,
        isCommanderCast: false,
        triggerScope: {
          sourceCountersTotal: Object.values(perm.counters).reduce(
            (total, count) => total + count,
            0,
          ),
        },
        ...(payload.x !== undefined ? { announcedX: payload.x } : {}),
      };

      // Boast's activation cost reduction, and {X} announced as part of this activation (CR
      // 602.1b) — folded into the `mana` cost component before payment, the same treatment
      // `costSpell`'s X gets.
      const activationReduction = activationCostReductionFor(
        ctx,
        player.id,
        perm.oracleId,
        perm.cardId,
        activated,
      );
      // The reduction applies once to the TOTAL mana cost with X announced (CR 601.2f), the way
      // `computePriorityOptions` priced it — spread across mana components, never applied twice.
      let reductionLeft = activationReduction.generic;
      const costsToPay = activated.costs.map((c) => {
        if (c.kind !== 'mana') return c;
        const announced = withX(c.cost, payload.x ?? 0);
        const reduced = subtractGeneric(announced, reductionLeft);
        reductionLeft -= announced.generic - reduced.generic;
        return { ...c, cost: reduced };
      });
      const [paymentScope, lifePaid] = yield* withLifePaidTally(
        ctx,
        payActivationCosts(ctx, player, perm, costsToPay, payload.x ?? 0),
      );
      if (perm.lastKnownFacts !== undefined) stackEntry.sourceFacts = perm.lastKnownFacts;
      if (paymentScope.stationPower !== undefined) {
        stackEntry.triggerScope = {
          ...stackEntry.triggerScope,
          stationPower: paymentScope.stationPower,
        };
      }
      // Recorded at ANNOUNCEMENT (CR 602.5f/606.3), not on resolution: the restriction is on
      // activating, so countering the ability does not give the activation back. A loyalty
      // ability is recorded even when `oncePerTurn` was left unset on its definition (e.g. a
      // hand-authored override) — CR 606.3's once-per-turn restriction comes from the loyalty
      // cost itself, not from that flag, so legal.ts's loyalty check must see it either way.
      if (activated.oncePerTurn === true || activated.costs.some((c) => c.kind === 'loyalty')) {
        perm.activationsThisTurn.push(payload.index);
      }
      if (activated.exhaust === true) {
        perm.exhaustedAbilities = [...(perm.exhaustedAbilities ?? []), payload.index];
      }
      s.stack.push(stackEntry);
      breakYieldsForStop(ctx, stackEntry);
      emit(
        ctx,
        'activateAbility',
        {
          player: player.id,
          source: perm.name,
          cardId: perm.cardId,
          description,
          targets: targets.filter((id): id is ObjectId => id !== undefined),
        },
        player.id,
      );
      debug(ctx, 'stack', `${player.id} activates ${perm.name} — ${description}`);
      queueWardTriggers(ctx, player.id, id, allTargets);
      queueBecomesTargetedTriggers(ctx, player.id, allTargets);
      queueActivationTriggers(ctx, stackEntry, lifePaid);
      return;
    }

    case 'foretell': {
      // Foretell (CR 702.143a/b): a special action during your turn — pay {2}, exile the card
      // face down. It keeps the foretell cost it had in hand (Dream Devourer's mana cost
      // reduced by {2}) and may be cast after this turn.
      const card = player.hand.find((candidate) => candidate.id === payload.objectId);
      const grant = gatherRuleStatics(ctx).find(
        (entry) => entry.static.kind === 'grantForetell' && entry.controllerId === player.id,
      );
      const def = card === undefined ? undefined : getDefByOracleId(ctx, card.oracleId, card.name);
      if (
        card === undefined ||
        grant === undefined ||
        grant.static.kind !== 'grantForetell' ||
        s.currentTurnPlayer !== player.id ||
        def === undefined ||
        def.types.includes('Land') ||
        def.manaCost === null
      ) {
        throw new Error('illegal action: this card cannot be foretold');
      }
      const foretellCost = subtractGeneric(def.manaCost, grant.static.reduction);
      yield* payManaCost(ctx, player, { ...emptyCost(), generic: 2 });
      const exiled = yield* moveObject(ctx, card, { zone: 'exile', faceDown: true });
      if (exiled !== null && exiled.zone === 'exile') {
        (exiled as EngineCardObject).foretold = { turn: s.turnNumber, cost: foretellCost };
      }
      emit(ctx, 'foretold', { player: player.id }, player.id);
      queuePlayerTriggersForEvent(ctx, 'foretells', player.id);
      return;
    }

    case 'turnFaceUp': {
      const perm = s.battlefield.find((candidate) => candidate.id === payload.objectId);
      const way =
        perm === undefined
          ? undefined
          : turnFaceUpCosts(perm, getDefByOracleId(ctx, perm.oracleId, perm.name)).find(
              (candidate) => candidate.via === payload.via,
            );
      if (
        perm === undefined ||
        perm.controllerId !== player.id ||
        perm.faceDown !== true ||
        way === undefined
      ) {
        throw new Error('illegal action: nothing to turn face up');
      }
      yield* payManaCost(ctx, player, way.cost);
      // CR 708.8: it keeps its status, counters and damage, and does not enter the battlefield.
      perm.faceDown = false;
      delete perm.manifested;
      perm.name = getDefByOracleId(ctx, perm.oracleId, perm.name).name;
      emit(ctx, 'turnedFaceUp', { name: perm.name, cardId: perm.cardId }, player.id);
      return;
    }

    case 'companionToHand': {
      const companion = player.companion;
      if (companion === null || player.companionMovedToHand) {
        throw new Error('engine bug: companion action without a companion');
      }
      yield* payManaCost(ctx, player, { ...emptyCost(), generic: 3 });
      player.companionMovedToHand = true;
      const handObj: EngineCardObject = {
        ...companion,
        id: `o-${s.nextObjectNum++}` as ObjectId,
        zone: 'hand',
      };
      player.hand.push(handObj);
      player.companion = null;
      emit(ctx, 'companionToHand', { player: player.id, name: companion.name }, player.id);
      return;
    }
  }
}

export { makePermanent };
